#!/usr/bin/env python3
"""Mini-Core frontend, monomorphic type checker and stack machine."""
import re
import sys

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(1500000)


class ParseFailure(Exception):
    pass


class TypeFailure(Exception):
    pass


# Integers index a graph of type equations. Each class has at most one
# constructor (Int, Bool or arrow); a class with no constructor is unknown.
class Types:
    def __init__(self):
        self.parent = [0, 1]
        self.shape = ['Int', 'Bool']

    def new(self, shape=None):
        i = len(self.parent)
        self.parent.append(i)
        self.shape.append(shape)
        return i

    def root(self, i):
        p = self.parent
        while i != p[i]:
            p[i] = p[p[i]]
            i = p[i]
        return i

    def unify(self, a, b):
        todo = [(a, b)]
        while todo:
            a, b = todo.pop()
            a, b = self.root(a), self.root(b)
            if a == b:
                continue
            s, t = self.shape[a], self.shape[b]
            if t is None:
                self.parent[b] = a
            elif s is None:
                self.parent[a] = b
            elif a < 2 or b < 2:
                raise TypeFailure
            else:
                self.parent[b] = a
                todo.extend(((s[0], t[0]), (s[1], t[1])))

    def check_finite(self):
        # Delayed occurs check: detect a directed cycle among the remaining
        # representatives. Do not expand DAGs to trees (potentially huge).
        state = bytearray(len(self.shape))

        def visit(i):
            i = self.root(i)
            if i < 2 or self.shape[i] is None or state[i] == 2:
                return
            if state[i] == 1:
                raise TypeFailure
            state[i] = 1
            a, b = self.shape[i]
            visit(a)
            visit(b)
            state[i] = 2

        for i in range(2, len(state)):
            if self.parent[i] == i:
                visit(i)


LEX = re.compile(r'[ \t\r\n\f\v]+|--[^\r\n]*|[A-Za-z_][A-Za-z0-9_]*|[0-9]+|->|//|==|[()/+*%<=:\-]|(.)')
KEYWORDS = {'let', 'rec', 'in', 'if', 'then', 'else', 'Int', 'Bool'}
BAD = {'_', 'match', 'with', 'type', 'forall'}


def tokens(text):
    if not text.isascii():
        raise ParseFailure
    for m in LEX.finditer(text):
        s = m[0]
        c = s[0]
        if c.isspace() and not m[1] or s.startswith('--'):
            continue
        if m[1] or s in BAD:
            raise ParseFailure
        if c.isdigit():
            yield ('lit', int(s))
        elif s == 'True' or s == 'False':
            yield ('lit', s == 'True')
        elif s in KEYWORDS:
            yield s
        elif c.isupper():
            raise ParseFailure
        elif c.islower() or c == '_':
            yield ('var', s)
        else:
            yield s
    yield None


class Parser:
    def __init__(self, text, types):
        self.stream = tokens(text)
        self.t = next(self.stream)
        self.types = types

    def take(self):
        t = self.t
        self.t = next(self.stream)
        return t

    def eat(self, s):
        if self.t == s:
            self.take()
            return True
        return False

    def need(self, s):
        if not self.eat(s):
            raise ParseFailure

    def ident(self):
        if type(self.t) is tuple and self.t[0] == 'var':
            return self.take()[1]
        raise ParseFailure

    def typeatom(self):
        if self.eat('Int'):
            return 0
        if self.eat('Bool'):
            return 1
        self.need('(')
        t = self.typ()
        self.need(')')
        return t

    def typ(self):
        args = []
        t = self.typeatom()
        while self.eat('->'):
            args.append(t)
            t = self.typeatom()
        for a in reversed(args):
            t = self.types.new((a, t))
        return t

    def expr(self):
        if self.eat('/'):
            x = self.ident()
            self.need('->')
            return ('lam', x, self.expr())
        if self.eat('let'):
            rec = self.eat('rec')
            x = self.ident()
            t = self.typ() if self.eat(':') else None
            if rec and t is None:
                raise ParseFailure
            self.need('=')
            rhs = self.expr()
            if rec and rhs[0] != 'lam':
                raise ParseFailure
            self.need('in')
            return ('rec' if rec else 'let', x, t, rhs, self.expr())
        if self.eat('if'):
            c = self.expr()
            self.need('then')
            a = self.expr()
            self.need('else')
            return ('if', c, a, self.expr())
        e = self.add()
        if self.t in ('==', '<'):
            e = (self.take(), e, self.add())
        return e

    def add(self):
        e = self.mul()
        while self.t in ('+', '-'):
            e = (self.take(), e, self.mul())
        return e

    def mul(self):
        e = self.app()
        while self.t in ('*', '//', '%'):
            e = (self.take(), e, self.app())
        return e

    def app(self):
        e = self.atom()
        while type(self.t) is tuple or self.t == '(':
            e = ('app', e, self.atom())
        return e

    def atom(self):
        if type(self.t) is tuple:
            return self.take()
        self.need('(')
        e = self.expr()
        if self.eat(':'):
            e = ('anno', e, self.typ())
        self.need(')')
        return e


# During static traversal the context maps names to (binding depth, type).
# Instruction operands for variables are relative lexical distances.
class Compiler:
    def __init__(self, types):
        self.types = types
        self.ctx = {}
        self.code = []
        self.depth = 0

    def enter(self, x, t):
        old = self.ctx.get(x)
        self.depth += 1
        self.ctx[x] = (self.depth, t)
        return old

    def leave(self, x, old):
        self.depth -= 1
        if old is None:
            del self.ctx[x]
        else:
            self.ctx[x] = old

    def function(self, e, recursive=False):
        _, x, body = e
        a = self.types.new()
        old = self.enter(x, a)
        pc = len(self.code)
        self.code.append(None)
        b = self.gen(body, True)
        self.code[pc] = ('reclose' if recursive else 'close', len(self.code))
        self.leave(x, old)
        return self.types.new((a, b))

    def gen(self, e, tail):
        """Emit code producing one operand (or returning it in tail position)."""
        op = e[0]
        ts = self.types
        emit = self.code.append
        if op == 'lit':
            t = int(type(e[1]) is bool)
            emit(('push', e[1]))
        elif op == 'var':
            binding = self.ctx.get(e[1])
            if binding is None:
                raise TypeFailure
            d, t = binding
            emit(('load', self.depth - d))
        elif op == 'anno':
            t = self.gen(e[1], tail)
            ts.unify(t, e[2])
            return t
        elif op == 'lam':
            t = self.function(e)
        elif op == 'app':
            f = self.gen(e[1], False)
            a = self.gen(e[2], False)
            t = ts.new()
            ts.unify(f, ts.new((a, t)))
            emit(('tail' if tail else 'call', 0))
            return t
        elif op == 'if':
            ts.unify(self.gen(e[1], False), 1)
            test = len(self.code)
            emit(None)
            a = self.gen(e[2], tail)
            if not tail:
                jump = len(self.code)
                emit(None)
            self.code[test] = ('jf', len(self.code))
            ts.unify(a, self.gen(e[3], tail))
            if not tail:
                self.code[jump] = ('jmp', len(self.code))
            return a
        elif op in ('let', 'rec'):
            _, x, ann, rhs, body = e
            if op == 'rec':
                old = self.enter(x, ann)
                r = self.function(rhs, recursive=True)
            else:
                r = self.gen(rhs, False)
                emit(('bind', 0))
                old = self.enter(x, r)
            if ann is not None:
                ts.unify(r, ann)
            t = self.gen(body, tail)
            self.leave(x, old)
            if not tail:
                emit(('unbind', 0))
            return t
        else:
            ts.unify(self.gen(e[1], False), 0)
            ts.unify(self.gen(e[2], False), 0)
            emit((op, 0))
            t = int(op in ('==', '<'))
        if tail:
            emit(('ret', 0))
        return t


def evaluate(code):
    vals = []
    calls = []
    pc = 0
    env = None
    while True:
        op, arg = code[pc]
        pc += 1
        if op == 'load':
            link = env
            while arg:
                link = link[1]
                arg -= 1
            vals.append(link[0])
        elif op == 'push':
            vals.append(arg)
        elif op == 'tail' or op == 'call':
            if op == 'call':
                calls.append((pc, env))
            value = vals.pop()
            pc, captured = vals.pop()
            env = (value, captured)
        elif op == 'ret':
            if not calls:
                return vals.pop()
            pc, env = calls.pop()
        elif op == 'jf':
            if not vals.pop():
                pc = arg
        elif op == 'jmp':
            pc = arg
        elif op == 'bind':
            env = (vals.pop(), env)
        elif op == 'unbind':
            env = env[1]
        elif op == 'close':
            vals.append((pc, env))
            pc = arg
        elif op == 'reclose':
            env = [None, env]
            env[0] = (pc, env)
            pc = arg
        else:
            b = vals.pop()
            a = vals[-1]
            if op == '+':
                vals[-1] = a + b
            elif op == '-':
                vals[-1] = a - b
            elif op == '*':
                vals[-1] = a * b
            elif op == '==':
                vals[-1] = a == b
            elif op == '<':
                vals[-1] = a < b
            elif op == '//':
                vals[-1] = a // b
            else:
                vals[-1] = a % b


def run(path):
    with open(path, 'rb') as f:
        data = f.read()
    if not data.isascii():
        raise ParseFailure
    types = Types()
    p = Parser(data.decode('ascii'), types)
    e = p.expr()
    if p.t is not None:
        raise ParseFailure
    c = Compiler(types)
    c.gen(e, True)
    types.check_finite()
    result = evaluate(c.code)
    return '<function>' if type(result) is tuple else result


if __name__ == '__main__':
    try:
        print(run(sys.argv[2]))
    except ParseFailure:
        print('ParseError')
        sys.exit(1)
    except TypeFailure:
        print('TypeError')
        sys.exit(1)
    except ZeroDivisionError:
        print('RuntimeError')
        sys.exit(1)
