"""Differential test: generate Mini-Core terms with known typing derivations,
and independently evaluate their translations to strict expressions in Python.
The Python input is entirely generated here, never user-provided source.
"""
import random
import runpy
import tempfile
from pathlib import Path


def show(t):
    return t if isinstance(t, str) else f'({show(t[0])}->{show(t[1])})'


class Programs(random.Random):
    def typ(self, depth=2):
        if not depth or self.randrange(3):
            return self.choice(('Int', 'Bool'))
        return self.typ(depth-1), self.typ(depth-1)

    def name(self):
        # Deliberately reuse names, so the oracle checks lexical shadowing.
        return self.choice('xyzabc')

    def term(self, t, ctx, depth):
        var = [x for x in ctx if ctx[x] == t]
        if var and self.random() < 0.35:
            x = self.choice(var)
            return x, x
        if depth > 0:
            form = self.randrange(9)
            if form == 0:
                m, p = self.term(t, ctx, depth-1)
                return f'({m}:{show(t)})', p
            if form == 1:
                c, d = self.term('Bool', ctx, depth-1)
                a, b = self.term(t, ctx, depth-1)
                e, f = self.term(t, ctx, depth-1)
                return f'(if {c} then {a} else {e})', f'({b} if {d} else {f})'
            if form in (2, 3):
                x, s = self.name(), self.typ()
                val, pv = self.term(s, ctx, depth-1)
                body, pb = self.term(t, ctx | {x: s}, depth-1)
                ann = ':' + show(s) if self.randrange(3) == 0 else ''
                return f'(let {x}{ann}={val} in {body})', f'(lambda {x}:{pb})({pv})'
            if form in (4, 5):
                s = self.typ()
                f, pf = self.term((s, t), ctx, depth-1)
                a, pa = self.term(s, ctx, depth-1)
                return f'({f} {a})', f'({pf})({pa})'
            if form in (6, 7) and isinstance(t, str):
                a, b = self.term('Int', ctx, depth-1)
                c, d = self.term('Int', ctx, depth-1)
                op = self.choice(('+', '-', '*', '//', '%') if t == 'Int' else ('<', '=='))
                return f'({a} {op} {c})', f'({b} {op} {d})'
        if t == 'Int':
            c = str(self.choice((0, 1, 2, 6, 24, 9007199254740993)))
            return c, c
        if t == 'Bool':
            c = self.choice(('True', 'False'))
            return c, c
        x = self.name()
        m, p = self.term(t[1], ctx | {x: t[0]}, max(0, depth-1))
        return f'(/{x}->{m})', f'(lambda {x}:{p})'


def differential(root, count=2500):
    impl = runpy.run_path(str(root / 'minicore'))
    rng = Programs(0x5A112)
    with tempfile.TemporaryDirectory() as d:
        path = Path(d) / 'generated.mc'
        for i in range(count):
            t = rng.typ()
            src, py = rng.term(t, {}, 5)
            if i % 13 == 0:
                src = f'if True then 1//0 else (({src}:{show(t)}):' + ('Bool' if t == 'Int' else 'Int') + ')'
                want = 'TypeError'
            elif i % 31 == 0:
                src = f'let nope = free in ({src} + if True then 1 else 0)'
                want = 'ParseError'
            else:
                try:
                    val = eval(py, {'__builtins__': {}})
                    want = '<function>' if callable(val) else str(val)
                except ZeroDivisionError:
                    want = 'RuntimeError'
            path.write_text(src)
            try:
                got = str(impl['run'](path))
            except impl['ParseFailure']:
                got = 'ParseError'
            except impl['TypeFailure']:
                got = 'TypeError'
            except ZeroDivisionError:
                got = 'RuntimeError'
            assert got == want, (src, py, want, got)
    print(f'{count} generated cases passed')
